-- SAT MASTER · 0029 · Topic videos on YouTube (drafts)
--
-- 33 free YouTube videos, one or two per SAT skill, added as DRAFT Resource Hub links (link only,
-- credited to the channel; nothing is copied or embedded). Students see none of them until an admin
-- runs "Check and publish drafts": each link is then checked from the server through YouTube oEmbed
-- (which answers only for a public video) and only working ones are published.
-- Data only: inserts into learning_resources; existing rows are not touched (on conflict do nothing).

insert into public.learning_resources (provider, provider_name, kind, title, description, url, language, subject_id, domain_id, skill_id, usage_terms, attribution, status, position)
select 'youtube', v.channel, 'video', v.title, v.description, v.url, 'en', d.subject_id, k.domain_id, k.id,
       'Link only. The video belongs to its creator; we do not copy or embed it.', v.attribution, 'draft', 100 + v.pos
from (values
  ('Digital SAT Advance Math Equivalent Expressions Beginners Part 1', 'Beginner walkthrough of Digital SAT Advanced Math equivalent-expression questions.', 'https://www.youtube.com/watch?v=-KOnm4EK0v8', 'EduretiX', 'Video by EduretiX on YouTube', 'equivalent_expressions', 0),
  ('SAT Math: Nonlinear Equations & Systems of Equations Explained | Advanced Math', 'Explains solving nonlinear equations and nonlinear systems as tested in SAT Advanced Math.', 'https://www.youtube.com/watch?v=bv2bHc8vMZs', 'Cascade Tutoring Center', 'Video by Cascade Tutoring Center on YouTube', 'nonlinear_equations_systems', 1),
  ('SAT Math on Khan Academy: Nonlinear Functions (Foundations)', 'Works through Khan Academy''s Digital SAT Nonlinear Functions (Foundations) practice.', 'https://www.youtube.com/watch?v=ZLp-3Z8jouo', 'Scalar Learning', 'Video by Scalar Learning on YouTube', 'nonlinear_functions', 2),
  ('SAT Math on Khan Academy: Quadratic and Exponential Word Problems (Foundations)', 'Covers quadratic and exponential models, the core of nonlinear-function word problems.', 'https://www.youtube.com/watch?v=YdvF3fVjLQk', 'Scalar Learning', 'Video by Scalar Learning on YouTube', 'nonlinear_functions', 3),
  ('SAT Math on Khan Academy: Linear Equation Word Problems (Foundations)', 'Builds and solves one-variable linear equations from Digital SAT word problems.', 'https://www.youtube.com/watch?v=qpMDefEdKL8', 'Scalar Learning', 'Video by Scalar Learning on YouTube', 'linear_equations_one_variable', 4),
  ('From Word Problems to Linear Equations in Two Variables - SAT® Math: 2.2', 'Lesson on writing two-variable linear equations from SAT word problems.', 'https://www.youtube.com/watch?v=Gw9Kx8OmdxE', 'Quizlet', 'Video by Quizlet on YouTube', 'linear_equations_two_variables', 5),
  ('SAT Math — Linear Functions | Cascade Tutoring Center', 'Dedicated lesson on SAT linear functions (slope, intercepts, interpretation).', 'https://www.youtube.com/watch?v=rRZO1N28OFQ', 'Cascade Tutoring Center', 'Video by Cascade Tutoring Center on YouTube', 'linear_functions', 6),
  ('Systems of Linear Inequalities in Two Variables - SAT® Math: 6.4', 'Lesson on linear inequalities in two variables for the current SAT.', 'https://www.youtube.com/watch?v=tlxdPZe-jq0', 'Quizlet', 'Video by Quizlet on YouTube', 'linear_inequalities', 7),
  ('SAT Math — Systems of Two Linear Equations | Cascade Tutoring Center', 'Dedicated lesson on systems of two linear equations in two variables.', 'https://www.youtube.com/watch?v=v-YVXD7gNc0', 'Cascade Tutoring Center', 'Video by Cascade Tutoring Center on YouTube', 'systems_linear_equations', 8),
