  ('SAT Math Prep: Inference from sample statistics and margin of error', 'Lesson named exactly after this Digital SAT skill.', 'https://www.youtube.com/watch?v=XNoPrWRqQq0', 'AP3 Tutoring', 'Video by AP3 Tutoring on YouTube', 'inference_margin_of_error', 15),
  ('SAT Math on Khan Academy: Center, Spread, and Shape of Distributions (Foundations)', 'Covers mean, median, spread and shape of one-variable data on the Digital SAT.', 'https://www.youtube.com/watch?v=HtkQbzDXKDA', 'Scalar Learning', 'Video by Scalar Learning on YouTube', 'one_variable_data', 16),
