  ('SAT Math on Khan Academy: Unit Conversion (Foundations)', 'Covers the unit-conversion part of this skill.', 'https://www.youtube.com/watch?v=K9fLV9mwYmY', 'Scalar Learning', 'Video by Scalar Learning on YouTube', 'ratios_rates_proportions_units', 20),
  ('SAT Math Prep: Two Variable Data: Model and Scatterplots', 'Lesson named after this Digital SAT skill (scatterplots, models).', 'https://www.youtube.com/watch?v=P3HUHN0B9fQ', 'AP3 Tutoring', 'Video by AP3 Tutoring on YouTube', 'two_variable_data', 21),
  ('How to Approach Cross-Text Connections Questions on the Digital SAT', 'Strategy for Digital SAT paired-text (cross-text) questions.', 'https://www.youtube.com/watch?v=EyqHcKfzBxo', 'Test Innovators', 'Video by Test Innovators on YouTube', 'cross_text_connections', 22),
  ('Avoid This Trap on Digital SAT Reading and Writing Test Structure and Purpose Questions', 'Explains a common trap on Digital SAT text structure and purpose questions.', 'https://www.youtube.com/watch?v=25KmWnTXu8o', 'Test Innovators', 'Video by Test Innovators on YouTube', 'text_structure_purpose', 23),
  ('Words in Context (Vocab) Questions on the Digital SAT: Strategies & Practice', 'Strategies and practice for Digital SAT words-in-context questions.', 'https://www.youtube.com/watch?v=dFQaoOGYhTk', 'Ivy League Mentors', 'Video by Ivy League Mentors on YouTube', 'words_in_context', 24),
  ('Rhetorical Synthesis Questions on the Digital SAT: Strategies & Practice', 'Strategies and practice for the notes-based rhetorical synthesis questions.', 'https://www.youtube.com/watch?v=lo7LFbac_9o', 'Ivy League Mentors', 'Video by Ivy League Mentors on YouTube', 'rhetorical_synthesis', 25),
  ('Transitions Questions on the Digital SAT: Strategies & Practice', 'Strategies and practice for Digital SAT transition questions.', 'https://www.youtube.com/watch?v=kz_P_b3H0oA', 'Ivy League Mentors', 'Video by Ivy League Mentors on YouTube', 'transitions', 26),
  ('Digital SAT - Information and Ideas - Central Ideas and Details - Foundation', 'Foundation-level lesson on Digital SAT central ideas and details questions.', 'https://www.youtube.com/watch?v=mfOyPCEpPdQ', 'InnoEd GED, SAT, IELTS', 'Video by InnoEd GED, SAT, IELTS on YouTube', 'central_ideas_details', 27),
  ('Digital SAT: Command of Quantitative Evidence (GRAPHS)', 'Shows how to use graph/table data to complete claims on the Digital SAT.', 'https://www.youtube.com/watch?v=J7Ka3-JwGxY', 'SAT Mastermind', 'Video by SAT Mastermind on YouTube', 'command_of_evidence_quantitative', 28),
  ('Command of Evidence Questions on the Digital SAT: Strategies & Practice', 'Covers textual evidence that supports or undermines a claim.', 'https://www.youtube.com/watch?v=POcYofMngBw', 'Ivy League Mentors', 'Video by Ivy League Mentors on YouTube', 'command_of_evidence_textual', 29),
  ('Inference Questions on the Digital SAT: Strategies & Practice (SAT Reading Prep)', 'Strategies and practice for Digital SAT inference (complete-the-text) questions.', 'https://www.youtube.com/watch?v=ANkK_ecpZZY', 'Ivy League Mentors', 'Video by Ivy League Mentors on YouTube', 'inferences', 30),
  ('Digital SAT Standard English Conventions: Boundaries', 'Lesson named after the Boundaries (punctuation) skill.', 'https://www.youtube.com/watch?v=M4EOqgOC4ks', 'Test Innovators', 'Video by Test Innovators on YouTube', 'boundaries', 31),
  ('DSAT R&W: The 3 Main Types of Verb Questions & How to Identify Them', 'Covers verb agreement/tense/form questions, the core of Form, Structure, and Sense.', 'https://www.youtube.com/watch?v=Dex3tUGv9Io', '3-4-5 Tutoring - SAT®, ACT® & More', 'Video by 3-4-5 Tutoring - SAT®, ACT® & More on YouTube', 'form_structure_sense', 32)
) as v(title, description, url, channel, attribution, skill_code, pos)
join public.skills k on k.code = v.skill_code
join public.domains d on d.id = k.domain_id
on conflict (url) do nothing;
